// Crash handling flow in V8:
// 1. CHECK/CHECK_EQ/DCHECK/FATAL/UNREACHABLE macro failure
//    -> CHECK_WITH_MSG -> CHECK_FAILED_HANDLER -> FATAL
// 2. FATAL macro -> V8_Fatal()
// 3. V8_Fatal() prints error message, optionally prints stack trace
//    -> OS::Abort()
// 4. OS::Abort() checks g_abort_mode:
//    - kExitWithSuccessAndIgnoreDcheckFailures: _exit(0) / ExitProcess(0)
//    - kExitWithFailureAndIgnoreDcheckFailures: _exit(-1) / ExitProcess(-1)
//    - kImmediateCrash: IMMEDIATE_CRASH() (hardware trap)
//    - kExitIfNoSecurityImpact: continue to abort()
//    - kDefault: abort()
// 5. abort() signals abnormal termination to OS

// Special cases:
// - FatalProcessOutOfMemory: Called when V8 can't allocate memory
//   -> May call embedder's OOM callback
//   -> base::FatalOOM() -> OS::Abort() or OS::ExitProcess()
// - FatalNoSecurityImpact: For non-security-critical crashes
//   -> Respects FatalErrorsWithNoSecurityImpactShouldExit()
//   -> OS::ExitProcess() or OS::Abort()

// Configuration:
// - g_abort_mode set in V8::Initialize() based on flags:
//   * --sandbox-fuzzing, --hole-fuzzing: kExitWithFailureAndIgnoreDcheckFailures
//   * --sandbox-testing: kExitWithSuccessAndIgnoreDcheckFailures
//   * --fuzzing, --allow-natives-for-differential-fuzzing: kExitIfNoSecurityImpact
//   * --hard-abort: kImmediateCrash
//   * default: kDefault

// Stack trace support:
// - base::SetPrintStackTrace() sets callback for printing stack traces
// - Called from V8::InitializePlatform()
// - Used in V8_Fatal() if g_print_stack_trace is set
// - Implemented in base/debug/stack_trace.cc

// Embedder hooks:
// - SetFatalErrorHandler(): Override default V8_Fatal behavior
// - SetOOMErrorHandler(): Override OOM handling
// - SetDcheckFunction(): Override DCHECK handling
